<form method="POST" action="{{ route('sales.store') }}" x-data="{items: [], discountRate: 0, add(p,u,mode){let i=this.items.findIndex(x=>x.product_id==p.id&&x.sale_unit_id==u.id);if(i>=0)this.items[i].quantity++;else this.items.push({product_id:p.id,sale_unit_id:u.id,name:p.name+' ('+mode+')',price:Number(u.selling_price),quantity:1})}, remove(i){this.items.splice(i,1)}, subtotal(){return this.items.reduce((s,i)=>s+i.price*i.quantity,0)}, total(){return this.subtotal()*(1-this.discountRate/100)}}" class="grid gap-6 lg:grid-cols-3">@csrf
<div class="rounded-xl border border-slate-800 bg-slate-900 p-4 sm:p-5 lg:col-span-2"><div class="mb-4 grid gap-3 sm:grid-cols-2"><input placeholder="Cari produk di kasir..." class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2" oninput="filterProducts(this.value)"><select name="customer_id" @change="discountRate=Number($event.target.selectedOptions[0].dataset.discount||0)" class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2"><option value="" data-discount="0">Pelanggan umum - 0%</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" data-discount="{{ $customer->discountPercent() }}">{{ $customer->name }} - {{ ucfirst($customer->membership_level) }} ({{ $customer->discountPercent() }}%)</option>@endforeach</select></div><div id="product-grid" class="grid gap-3 sm:grid-cols-2">@foreach($products as $product)<div data-name="{{ strtolower($product->name) }}" class="product-card rounded-xl border border-slate-700 bg-slate-950 p-4">@if($product->image_path)<img src="{{ asset('storage/'.$product->image_path) }}" alt="{{ $product->name }}" class="mb-3 h-28 w-full rounded-lg object-cover">@endif<p class="font-semibold">{{ $product->name }}</p><p class="text-xs text-slate-500">{{ $product->sku }} · stok {{ $product->type === 'service' ? 'jasa' : $product->stock.' '.$product->unit }}</p><div class="mt-3 grid gap-2 {{ $product->saleUnits->count() > 1 ? 'grid-cols-2' : 'grid-cols-1' }}">@foreach($product->saleUnits as $saleUnit)<button type="button" @click='add(@json($product), @json($saleUnit), "{{ $saleUnit->conversion > 1 ? 'Grosir' : 'Eceran' }}")' class="rounded-lg border border-slate-700 px-3 py-2 text-left hover:border-emerald-400"><span class="block text-xs font-bold uppercase text-slate-400">{{ $saleUnit->conversion > 1 ? 'Grosir' : 'Eceran' }}</span><span class="block text-xs text-slate-500">{{ $saleUnit->conversion > 1 ? $saleUnit->name.' · '.$saleUnit->conversion.' '.$product->unit : $product->unit }}</span><b class="mt-1 block text-emerald-300">Rp {{ number_format($saleUnit->selling_price, 0, ',', '.') }}</b></button>@endforeach</div></div>@endforeach</div></div>
<div class="h-fit rounded-xl border border-slate-800 bg-slate-900 p-4 sm:p-5 lg:sticky lg:top-5"><h2 class="mb-4 font-bold">Keranjang</h2><div class="space-y-3"><div x-show="items.length===0" class="py-8 text-center text-sm text-slate-500">Pilih mode eceran atau grosir.</div><template x-for="(item,index) in items" :key="item.product_id+'-'+item.sale_unit_id"><div class="flex justify-between gap-2 border-b border-slate-800 pb-3"><div><p x-text="item.name" class="text-sm font-medium"></p><input type="hidden" :name="'items['+index+'][product_id]'" :value="item.product_id"><input type="hidden" :name="'items['+index+'][sale_unit_id]'" :value="item.sale_unit_id"><input type="number" min="1" :name="'items['+index+'][quantity]'" x-model="item.quantity" class="mt-1 w-16 rounded border border-slate-700 bg-slate-950 px-2 py-1 text-xs"></div><div class="text-right"><p x-text="'Rp '+(item.price*item.quantity).toLocaleString('id-ID')" class="text-sm"></p><button type="button" @click="remove(index)" class="text-xs text-red-300">hapus</button></div></div></template></div><div class="mt-5 border-t border-slate-700 pt-4"><div class="flex justify-between text-xs text-emerald-300"><span>Diskon pelanggan</span><span x-text="discountRate+'%'"></span></div><div class="flex justify-between text-lg font-bold"><span>Total</span><span x-text="'Rp '+total().toLocaleString('id-ID')"></span></div><input type="hidden" name="discount" value="0"><input type="hidden" name="tax" value="0"><label class="mt-4 block text-sm">Dibayar<input name="paid_amount" type="number" min="0" required class="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2"></label><select name="payment_method" class="mt-3 w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="card">Kartu</option><option value="transfer">Transfer</option></select><button class="mt-4 w-full rounded-lg bg-emerald-400 py-3 font-bold text-slate-950">Simpan transaksi</button></div></div></form><script src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js" defer></script><script>function filterProducts(value){document.querySelectorAll('.product-card').forEach(e=>e.style.display=e.dataset.name.includes(value.toLowerCase())?'block':'none')}</script>
